import { randomInt } from 'node:crypto';

/** Valid identifiers, generated by their algorithms (tasks 2-2 and 2-3). */

export function nationalId(): string {
  for (;;) {
    const body = Array.from({ length: 9 }, () => randomInt(10));
    const sum = body.reduce((s, d, i) => s + d * (10 - i), 0);
    const r = sum % 11;
    const id = `${body.join('')}${String(r < 2 ? r : 11 - r)}`;
    if (!/^(\d)\1{9}$/.test(id)) return id;
  }
}

export function legalId(): string {
  for (;;) {
    const d = Array.from({ length: 10 }, () => randomInt(10));
    if (d.slice(3, 9).every((x) => x === 0)) continue;
    const e = (d[9] ?? 0) + 2;
    const w = [29, 27, 23, 19, 17, 29, 27, 23, 19, 17];
    const sum = d.reduce((s, x, i) => s + (x + e) * (w[i] ?? 0), 0);
    return `${d.join('')}${String(sum % 11 === 10 ? 0 : sum % 11)}`;
  }
}

export function sheba(): string {
  const bban = `0${Array.from({ length: 21 }, () => randomInt(10)).join('')}`;
  const numeric = `${bban}182700`; // I = 18, R = 27, check digits 00
  let rem = 0;
  for (const ch of numeric) rem = (rem * 10 + Number(ch)) % 97;
  return `IR${String(98 - rem).padStart(2, '0')}${bban}`;
}

/** A medical council number no other test is likely to have used. */
export const councilNumber = () => String(randomInt(10_000_000, 99_999_999));
